"Xiaobao câu · Nhìn tranh chữ Hán, câu cá tiếng Anh": "Xiaobao fishes · Look at the character picture, fish in English",
"Đua vịt: thứ, tháng, buổi, việc hằng ngày, sở thích": "Duck race: days, months, parts of day, daily routine, hobbies",
