"Nhìn tranh. Câu nào là câu HỎI “{}” bằng tiếng Trung?": "Look at the picture. Which sentence is the QUESTION “{}” in Chinese?",
"Trò chơi từ vựng: nhìn tranh, chọn đúng tên nơi chốn.": "Vocabulary game: look at the picture, choose the right place name.",
"Tối đa 4 người thân thôi nhé. Bỏ bớt một người trước.": "Maximum 4 family members. Remove one first.",
"Viết phần trên trước: ngang, sổ, ngang dài, phẩy dài.": "Write the top part first: horizontal, vertical, long horizontal, long left-falling.",
"Bẫy: employee bắt đầu bằng âm “e”, nên nói an employee.": "Trap: employee starts with the sound “e”, so say an employee.",
"Thẻ từ: dễ thương, gầy – béo, trẻ – già, xấu – xinh đẹp": "Word cards: cute, thin – fat, young – old, ugly – beautiful",
