"Bấm ◀ ▶ hoặc chạm vào tủ kính để đưa cần gắp tới một bạn thú, rồi bấm “Gắp”.": "Press ◀ ▶ or tap the glass case to move the claw to a plushie, then press “Grab”.",
"Ối, cần gắp không trúng bạn thú nào. Đưa cần tới ngay trên một bạn thú rồi gắp lại nhé!": "Oops, the claw missed every plushie. Move it right above a plushie and grab again!",
"Play the three games in order. · Chơi lần lượt 3 trò chơi. Mỗi trò mở trong một thẻ mới. Mở đủ 3 trò để được 1 sao.": "Play the three games in order. Each game opens in a new tab. Open all 3 games to earn 1 star.",
"Các chữ màu đỏ lấy từ thẻ chữ tượng hình. Chọn pinyin đúng của cả từ. Nhìn kỹ: wǔfàn – wǎnfàn, zǎoshang – wǎnshang. Bấm loa để nghe từng đáp án.": "The red characters come from the pictograph cards. Choose the correct pinyin of the whole word. Look closely: wǔfàn – wǎnfàn, zǎoshang – wǎnshang. Press the speaker to hear each answer.",
"Lên kế hoạch một tuần của con: kéo hoạt động vào đúng ngày và buổi, chọn giờ, rồi quay video kể về tuần của con theo mẫu “On Tuesday, I read books at eight o’clock in the morning.”": "Plan your week: drag activities to the right day and part of day, choose times, then record a video about your week using the pattern “On Tuesday, I read books at eight o’clock in the morning.”",
"Read the text and choose the best answer. Paul is talking to his friend Alex. Drag the right answer into Alex’s speech bubble (or tap it). · Kéo câu trả lời đúng vào bóng nói của Alex.": "Read the text and choose the best answer. Paul is talking to his friend Alex. Drag the right answer into Alex’s speech bubble (or tap it).",
"Nhờ ba mẹ dùng camera điện thoại quay con đọc kịch bản (bấm “Chữ to để quay video” để kịch bản hiện chữ to). Quay xong, chọn video ở nút dưới để xem lại trên trang này, rồi gửi video cho cô qua nhóm lớp.": "Ask your parents to use a phone camera to record you reading the script (press “Big letters for recording” to show the script in big letters). When done, choose the video with the button below to watch it here, then send the video to your teacher via the class group.",
