"Thẻ từ: máy bay, tàu hỏa, đi bộ · đi đâu bằng gì?": "Word cards: plane, train, walking · where to, by what?",
"I ride a bike to the park. Chọn câu tiếng Trung đúng.": "I ride a bike to the park. Choose the right Chinese sentence.",
"Bạn đi công viên bằng gì? Tớ đạp xe đạp đến công viên.": "How do you go to the park? I ride a bicycle to the park.",
"Bunny hỏi “{}”. Nhìn tranh, chọn câu trả lời tiếng Trung đúng:": "Bunny asks “{}”. Look at the picture, choose the right Chinese answer:",
"Chạm vào nơi con hay đi ở bước 1, rồi chọn cách con đi đến đó.": "Tap a place you often go in step 1, then choose how you get there.",
"Nghe “What is this?”. Nhìn tranh, chọn câu trả lời tiếng Trung:": "Listen to “What is this?”. Look at the picture, choose the Chinese answer:",
"Các bạn đi công viên bằng gì? Chúng tớ đi xe buýt đến công viên!": "How do you all go to the park? We go to the park by bus!",
"Nhìn tranh. Câu nào là câu HỎI “What is this?” bằng tiếng Trung?": "Look at the picture. Which sentence is the QUESTION “What is this?” in Chinese?",
"Thẻ từ: ô tô, xe buýt, xe đạp, xe máy · đạp xe, lái xe, đi xe buýt": "Word cards: car, bus, bicycle, motorbike · ride, drive, take the bus",
"Nghe câu hỏi “What is this?”, nhìn tranh, trả lời bằng tiếng Trung:": "Listen to the question “What is this?”, look at the picture, answer in Chinese:",
"Chạm vào một nơi để đổi cách đi, hoặc chọn thêm nơi khác (tối đa 4).": "Tap a place to change how you go, or choose another place (up to 4).",
"Chọn ít nhất một nơi và cách con đi đến đó để kịch bản hiện ra ở đây.": "Choose at least one place and how you get there for the script to appear here.",
"Bunny hỏi “What is this?”. Nhìn tranh, chọn câu trả lời tiếng Trung đúng:": "Bunny asks “What is this?”. Look at the picture, choose the right Chinese answer:",
"Kéo mỗi từ vào đúng chấm tròn trong tranh (hoặc bấm một từ rồi bấm vào chấm).": "Drag each word onto the right dot in the picture (or press a word, then press the dot).",
"Các chữ màu đỏ ghép lại thành một từ. Chọn pinyin đúng của cả từ. Bấm loa để nghe từng đáp án.": "The red characters combine into one word. Choose the correct pinyin of the whole word. Press the speaker to hear each answer.",
"Three parts: drag and drop, draw lines, make sentences. · Ba phần: kéo thả từ vào số, nối câu theo tranh, viết 6 câu.": "Three parts: drag and drop, draw lines, make sentences. Three parts: drag words onto the numbers, connect sentences to the pictures, write 6 sentences.",
"Write the 6 sentences about the picture. Start with a capital letter and end with a full stop. · Viết 6 câu về bức tranh.": "Write the 6 sentences about the picture. Start with a capital letter and end with a full stop.",
"👉 Click one box in each column (1 → 2 → 3 → 4) to make a sentence about the picture. · Chọn mỗi cột một ô để ghép thành câu.": "👉 Click one box in each column (1 → 2 → 3 → 4) to make a sentence about the picture.",
"Các chữ màu đỏ ghép lại thành một từ. Chọn pinyin đúng của cả từ. Bắt đầu từ từ ngắn (1–2 âm), sau đó dài dần. Bấm loa để nghe từng đáp án.": "The red characters combine into one word. Choose the correct pinyin of the whole word. Start with short words (1–2 sounds), then longer ones. Press the speaker to hear each answer.",
"Chọn từ rồi chọn cách luyện: Xem mẫu, Tô nét, Tự viết. Bấm “Hiện hình minh họa” để thấy chữ được vẽ từ hình gì. Tô xong tất cả các chữ để được 1 sao.": "Choose a word, then a way to practice: See model, Trace, Write it yourself. Press “Show illustration” to see what picture the character was drawn from. Trace all characters to earn 1 star.",
"Listen and draw lines. There is one example. · Nghe và nối tên với đúng bạn trong tranh: kéo tên vào bạn đó, hoặc bấm tên rồi bấm vào bạn trong tranh.": "Listen and draw lines. There is one example. Listen and connect each name to the right friend in the picture: drag the name onto that friend, or press the name then press the friend in the picture.",
"Look at the pictures. Write the words. · Nhìn tranh, điền từ vào ô chữ. Bấm một bức tranh (hoặc một ô) rồi gõ chữ; bấm lại ô giao nhau để đổi hàng ngang / dọc.": "Look at the pictures. Write the words. Look at the pictures and fill the words into the crossword. Press a picture (or a box) then type; press the crossing box again to switch across / down.",
"Chọn từ rồi chọn cách luyện: Xem mẫu, Tô nét, Tự viết. Chữ có tranh minh họa thì bấm “Hiện hình minh họa” để thấy chữ được vẽ từ hình gì. Tô xong tất cả các chữ để được 1 sao.": "Choose a word, then a way to practice: See model, Trace, Write it yourself. For characters with an illustration, press “Show illustration” to see what picture the character was drawn from. Trace all characters to earn 1 star.",
