"Nhờ ba mẹ dùng camera điện thoại quay con đọc kịch bản (bấm “Chữ to để quay video” để kịch bản hiện chữ to). Có thể cầm ảnh gia đình khi quay. Quay xong, chọn video ở nút dưới để xem lại, rồi gửi cho cô qua nhóm lớp.": "Ask your parents to use a phone camera to record you reading the script (press “Big letters for recording” to show the script in big letters). You can hold a family photo while recording. When done, choose the video with the button below to watch it, then send it to your teacher via the class group.",
