"BRIDGE 1 · Nhận diện từ · ôn bài 1": "BRIDGE 1 · Recognizing words · review lesson 1",
"Ngang dài, rồi sổ dài xuyên xuống.": "Long horizontal, then long vertical going down.",
"). Con vẽ {} ở bước 1 trước đã nhé!": "). Draw {} in step 1 first!",
