"Thẻ từ: cây, hoa, đá, cỏ, sông, núi": "Word cards: tree, flower, stone, grass, river, mountain",
"I see the sky. Chọn câu tiếng Trung đúng.": "I see the sky. Choose the right Chinese sentence.",
"Sổ gập: bên trái xuống rồi kéo ngang ở đáy.": "Vertical-fold: left side down, then horizontal at the bottom.",
"Tranh của con còn trống. Chọn ở bước 1 nhé!": "Your picture is still empty. Choose in step 1!",
"Thẻ từ: mặt trời, mặt trăng, ngôi sao, bầu trời": "Word cards: sun, moon, stars, sky",
"Chọn những thứ con vẽ để kịch bản hiện ra ở đây.": "Choose the things you drew for the script to appear here.",
"Bẫy: tiếng Anh cần “a” trước tên đồ vật: I see {}.": "Trap: English needs “a” before an object name: I see {}.",
"My big brother sees the mountains. Chọn câu tiếng Trung đúng.": "My big brother sees the mountains. Choose the right Chinese sentence.",
"Bẫy: grass (cỏ) không đếm được, không có “a”. Nói I see grass.": "Trap: grass is uncountable, no “a”. Say I see grass.",
"The little bird’s home is in the tree. Chọn câu tiếng Trung đúng.": "The little bird’s home is in the tree. Choose the right Chinese sentence.",
"Nghe “What do you see?”. Nhìn tranh, chọn câu trả lời tiếng Trung:": "Listen to “What do you see?”. Look at the picture, choose the Chinese answer:",
"Nhìn tranh. Câu nào là câu HỎI “What do you see?” bằng tiếng Trung?": "Look at the picture. Which sentence is the QUESTION “What do you see?” in Chinese?",
"Chạm vào một bạn thú. Bạn ấy sẽ về nhà nếu tranh của con có nhà của bạn ấy.": "Tap an animal friend. They go home if your picture has their home.",
"Bunny hỏi “What do you see?”. Nhìn tranh, chọn câu trả lời tiếng Trung đúng:": "Bunny asks “What do you see?”. Look at the picture, choose the right Chinese answer:",
"Làm lần lượt 3 phần: 1 nghe và viết số · 2 đọc và chọn a hoặc b · 3 kể lại truyện. ·": "Do the 3 parts in turn: 1 listen and write numbers · 2 read and choose a or b · 3 retell the story.",
"). Nhìn lại 6 bức tranh ở phần 1 và kể lại cả câu chuyện theo thứ tự, dùng thì quá khứ.": "). Look again at the 6 pictures in part 1 and retell the whole story in order, using the past tense.",
"Nghe và viết số 2–6 vào ô trắng của từng bức tranh theo thứ tự con nghe. Có một ví dụ (số 1). Chạm vào ô trắng để chọn số.": "Listen and write numbers 2–6 in the white box of each picture in the order you hear. There is one example (number 1). Tap a white box to choose a number.",
"Lật 1 thẻ tiếng Anh và 1 thẻ tiếng Trung (chạm để nghe). Cùng nghĩa thì chọn V, khác nghĩa chọn X. Ghép hết 6 cặp để được 1 sao.": "Flip 1 English card and 1 Chinese card (tap to listen). Same meaning: choose ✓, different meaning: choose ✗. Match all 6 pairs to earn 1 star.",
"Chọn pinyin đúng của chữ (hoặc của cả từ). Các đáp án còn lại là pinyin của những từ khác trong bài. Bấm loa để nghe từng đáp án.": "Choose the correct pinyin of the character (or the whole word). The other answers are the pinyin of other words in the lesson. Press the speaker to hear each answer.",
"Drag each word to the right circle in the picture. · Kéo mỗi từ vào đúng chấm tròn trong tranh (hoặc bấm một từ rồi bấm vào chấm).": "Drag each word to the right circle in the picture.",
"Đọc và nghe câu trong truyện rồi chọn đáp án đúng. Tranh hiện ra sau khi con trả lời đúng. Trả lời sai thì pinyin hiện ra để con đọc lại và thử lần nữa.": "Read and listen to the story sentence, then choose the right answer. The picture appears after you answer correctly. If you answer wrong, pinyin appears so you can read again and try once more.",
"Read the story. Choose a word from the story to complete each sentence (1, 2 or 3 words). · Đọc truyện, viết 1, 2 hoặc 3 từ để hoàn thành mỗi câu. Có một ví dụ.": "Read the story. Choose a word from the story to complete each sentence (1, 2 or 3 words). Write 1, 2 or 3 words to complete each sentence. There is one example.",
"Chọn từ rồi chọn cách luyện: Xem mẫu, Tô nét, Tự viết. Mỗi chữ có tranh chữ tượng hình mờ phía sau ô viết; chỉnh độ mờ hoặc bấm “Kéo hình” nếu cần. Tô xong tất cả các chữ để được 1 sao.": "Choose a word, then a way to practice: See model, Trace, Write it yourself. Each character has a faint pictograph behind the writing box; adjust the fade or press “Drag picture” if needed. Trace all characters to earn 1 star.",
"Nhờ ba mẹ dùng camera điện thoại quay con vừa chỉ vào tranh vừa đọc kịch bản (có thể vẽ tranh thật ra giấy rồi cầm lên khi quay). Quay xong, chọn video ở nút dưới để xem lại, rồi gửi cho cô qua nhóm lớp.": "Ask your parents to use a phone camera to record you pointing at the picture while reading the script (you can draw a real picture on paper and hold it up while recording). When done, choose the video with the button below to watch it, then send it to your teacher via the class group.",
"Chọn từ rồi chọn cách luyện: Xem mẫu, Tô nét, Tự viết. Mỗi chữ có tranh chữ tượng hình mờ phía sau ô viết; chỉnh độ mờ hoặc bấm “Kéo hình” nếu cần. Đọc mẹo nhớ để biết chữ được vẽ từ hình gì. Tô xong tất cả các chữ để được 1 sao.": "Choose a word, then a way to practice: See model, Trace, Write it yourself. Each character has a faint pictograph behind the writing box; adjust the fade or press “Drag picture” if needed. Read the memory tip to see what picture the character was drawn from. Trace all characters to earn 1 star.",
"Bấm QUAY! Vòng quay dừng ở ô nào thì làm theo ô đó: ô 100 là câu dễ, ô 200 – 300 là câu khó nhiều điểm, ô MẤT LƯỢT bị trừ 50 điểm, ô BÍ MẬT có quà bất ngờ (cộng điểm, thêm giờ, thêm mạng, gợi ý). Câu hỏi lấy từ truyện, không có tranh: tranh hiện ra sau khi trả lời. Câu cuối cùng là CÂU HỎI VÀNG, điểm nhân đôi!": "Press SPIN! Do what the box says where the wheel stops: 100 is an easy question, 200 – 300 are hard questions with lots of points, LOSE A TURN deducts 50 points, SECRET has a surprise gift (points, extra time, extra life, hint). Questions come from the story and have no pictures: the picture appears after you answer. The last one is the GOLDEN QUESTION, double points!",
