"Phía sau nhà chúng tớ có cây to.": "Behind our house there is a big tree.",
"BRIDGE 2 · Câu hỏi và câu trả lời": "BRIDGE 2 · Questions and answers",
"Cây to chính là nhà của chim nhỏ.": "The big tree is the little bird's home.",
"Quay video giới thiệu nhà của con": "Record a video introducing your home",
